package drone_battery_charge_supervisor.Drone_Battery_Charge_Supervisor

import org.sireum._
import art._
import drone_battery_charge_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Charge_Context_Qualification_Api {
  def id: Art.BridgeId
  def charger_sample_Id : Art.PortId
  def flight_sample_Id : Art.PortId
  def charge_context_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var charge_context: Drone_Battery_Charge_Supervisor.ChargeContext.Type = $

  def put_charge_context(value : Drone_Battery_Charge_Supervisor.ChargeContext.Type) : Unit = {
    Contract(
      Modifies(charge_context),
      Ensures(
        charge_context == value
      )
    )
    Spec {
      charge_context = value
    }

    Art.putValue(charge_context_Id, Drone_Battery_Charge_Supervisor.ChargeContext_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Charge_Context_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val charger_sample_Id : Art.PortId,
  val flight_sample_Id : Art.PortId,
  val charge_context_Id : Art.PortId) extends Charge_Context_Qualification_Api

@datatype class Charge_Context_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val charger_sample_Id : Art.PortId,
  val flight_sample_Id : Art.PortId,
  val charge_context_Id : Art.PortId) extends Charge_Context_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var charger_sample: Drone_Battery_Charge_Supervisor.ChargerSample = $

  def get_charger_sample() : Option[Drone_Battery_Charge_Supervisor.ChargerSample] = {
    Contract(
      Ensures(
        Res == Some(charger_sample)
      )
    )
    val value : Option[Drone_Battery_Charge_Supervisor.ChargerSample] = Art.getValue(charger_sample_Id) match {
      case Some(Drone_Battery_Charge_Supervisor.ChargerSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port charger_sample.  Expecting 'Drone_Battery_Charge_Supervisor.ChargerSample_Payload' but received ${v}")
        None[Drone_Battery_Charge_Supervisor.ChargerSample]()
      case _ => None[Drone_Battery_Charge_Supervisor.ChargerSample]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var flight_sample: Drone_Battery_Charge_Supervisor.FlightActivitySample = $

  def get_flight_sample() : Option[Drone_Battery_Charge_Supervisor.FlightActivitySample] = {
    Contract(
      Ensures(
        Res == Some(flight_sample)
      )
    )
    val value : Option[Drone_Battery_Charge_Supervisor.FlightActivitySample] = Art.getValue(flight_sample_Id) match {
      case Some(Drone_Battery_Charge_Supervisor.FlightActivitySample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port flight_sample.  Expecting 'Drone_Battery_Charge_Supervisor.FlightActivitySample_Payload' but received ${v}")
        None[Drone_Battery_Charge_Supervisor.FlightActivitySample]()
      case _ => None[Drone_Battery_Charge_Supervisor.FlightActivitySample]()
    }
    return value
  }
}
